create or replace function private.flag_payment_velocity() returns trigger language plpgsql security definer set search_path='' as $$ declare recent_count integer; begin select count(*)::integer into recent_count from public.payment_attempts where organization_id=new.organization_id and event_id=new.event_id and created_at>now()-interval '10 minutes' and status in ('created','pending'); if recent_count>=20 then insert into public.moderation_flags(organization_id,event_id,kind,severity,details) values(new.organization_id,new.event_id,'payment_attempt_velocity',least(5,2+(recent_count/50)),'There have been '||recent_count||' pending payment attempts for this event in the last ten minutes.'); end if; return new; end $$;
drop trigger if exists payment_velocity_flag on public.payment_attempts;
create trigger payment_velocity_flag after insert on public.payment_attempts for each row execute function private.flag_payment_velocity();
